begin;

insert into destinations (slug,title,category,location,image_url,description,base_price,rating_avg) values ('situ-buleud','Trip to Situ Buleud & Air Mancur Sri Baduga','Cagar Budaya Sunda','Nagri Kidul, Kec. Purwakarta, Kab. Purwakarta','https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=800&q=80','Danau cagar budaya seluas 4 hektar era kolonial dengan atraksi air mancur menari berlaser terbesar dan sentra kuliner Sate Maranggi.',35000,4.70) on conflict (slug) do nothing;
insert into meeting_points (destination_id,name,description) select id,'Stasiun Purwakarta','Pintu keluar barat dekat patung cagar budaya.' from destinations where slug='situ-buleud' and not exists (select 1 from meeting_points mp where mp.destination_id=destinations.id and mp.name='Stasiun Purwakarta');
insert into meeting_points (destination_id,name,description) select id,'Alun-Alun Purwakarta','Depan gapura cagar budaya masjid agung.' from destinations where slug='situ-buleud' and not exists (select 1 from meeting_points mp where mp.destination_id=destinations.id and mp.name='Alun-Alun Purwakarta');
insert into meeting_points (destination_id,name,description) select id,'Plaza Air Mancur Sri Baduga','Pintu gerbang utama danau Situ Buleud.' from destinations where slug='situ-buleud' and not exists (select 1 from meeting_points mp where mp.destination_id=destinations.id and mp.name='Plaza Air Mancur Sri Baduga');
insert into destinations (slug,title,category,location,image_url,description,base_price,rating_avg) values ('gracia-spa','Gracia Spa Hot Spring Pool','Air Panas & Curug','Desa Cikondang, Kec. Ciater, Kabupaten Subang','https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80','Pemandian air panas alami belerang di tengah hamparan kebun teh Ciater dengan udara pegunungan yang sangat sejuk.',100000,4.60) on conflict (slug) do nothing;
insert into meeting_points (destination_id,name,description) select id,'Gerbang Utama Gracia Spa Ciater','Lobi penerimaan tamu dan parkir wisata.' from destinations where slug='gracia-spa' and not exists (select 1 from meeting_points mp where mp.destination_id=destinations.id and mp.name='Gerbang Utama Gracia Spa Ciater');
