insert into destinations (slug,title,category,location,image_url,description,base_price,rating_avg) values ('curug-tilu','Curug Tilu & Kolam Alami Ciririp','Air Panas & Curug','Desa Ciririp, Kec. Sukasari, Kab. Purwakarta','https://images.unsplash.com/photo-1546587348-d12660c30c50?auto=format&fit=crop&w=800&q=80','Green Canyon mini Purwakarta dengan air toska jernih alami berundak tiga, tebing eksotis, dan persewaan pelampung.',40000,4.55) on conflict (slug) do nothing;
