insert into destinations (slug,title,category,location,image_url,description,base_price,rating_avg) values ('benteng-vredeburg','Museum Benteng Vredeburg','Cagar Budaya Nasional','Ngupasan, Kec. Gondomanan, Kota Yogyakarta','https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?auto=format&fit=crop&w=800&q=80','Benteng kolonial bersejarah abad ke-18 dengan diorama lengkap perjuangan nasional dan arsitektur peninggalan Belanda.',14000,4.70) on conflict (slug) do nothing;
