insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('none','Kendaraan Mandiri / Bertemu di Titik Kumpul','Peserta berangkat memakai kendaraan pribadi atau transportasi umum sendiri, dan langsung bertemu pemandu di Meeting Point yang disepakati.','https://images.unsplash.com/photo-1449965408869-eaa3f722e40d?auto=format&fit=crop&w=400&q=80','Paling Fleksibel','Tanpa Batasan Peserta (Mandiri)',1,9999,0,array['Bebas Jam Tiba Mandiri','Koordinasi Langsung via WhatsApp Pemandu','Parkir Wisata Aman & Tersedia']::text[],array['Meeting Point Utama Wisata','Pintu Masuk Destinasi']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('ojek','Ojek Wisata Lokal Purwakarta (Driver + Helm SNI)','Armada sepeda motor dengan driver pemandu lokal. Sangat lincah menembus gang desa, jalan perbukitan sempit, dan hidden spot tersembunyi.','https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=400&q=80','Cocok Solo Traveler','Kapasitas 1 Orang / Unit Motor',1,1,45000,array['Driver Ramah Hafal Rute Lokal','Helm SNI Bersih & Wangi','BBM Sudah Termasuk','Jas Hujan Tersedia']::text[],array['Stasiun Purwakarta','Alun-Alun','Hotel Area Kota']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('avanza','Mobil Avanza / Xenia Pariwisata AC (1-6 Kursi)','Mobil keluarga nyaman dengan AC sejuk, audio santai, dan driver lokal berpengalaman. Siap antar-jemput dari stasiun atau hotel.','https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=400&q=80','Favorit 3-6 Orang','Kapasitas 1 - 6 Kursi Penumpang',1,6,300000,array['AC Double Blower Dingin','Driver Sopan & Tidak Merokok','BBM & Parkir Termasuk','Charger HP USB']::text[],array['Stasiun Purwakarta','Hotel / Penginapan','Alun-Alun']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('jeep-4x4','Jeep 4x4 Offroad Wisata Petualangan','Sensasi petualangan offroad menembus lereng bukit, jalur bebatuan air terjun, dan spot sunrise pegunungan ekstrem yang tidak bisa dijangkau mobil biasa.','https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=400&q=80','Sensasi Petualangan','Kapasitas 1 - 4 Kursi Penumpang',1,4,450000,array['Driver Pro Bersertifikat Offroad','Unit Jeep 4WD Tangguh Terawat','Spot Foto Instagramable Atap Terbuka','BBM Sudah Termasuk']::text[],array['Basecamp Lereng Gunung','Rest Area Wanayasa','Stasiun Purwakarta']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('hiace','Toyota HiAce Commuter Pariwisata AC','Minivan eksekutif dengan suspensi empuk, kabin senyap, dan AC double blower merata. Sangat ideal untuk keluarga besar & rombongan sedang.','https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=400&q=80','Favorit 10-14 Orang','Kapasitas 10 - 14 Kursi Penumpang',4,14,650000,array['AC Double Blower Dingin Merata','Driver Berpengalaman Ramah','BBM Sudah Termasuk','Port USB Charger Tiap Kursi']::text[],array['Stasiun Purwakarta','Lobi Hotel','Meeting Point Pilihan']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('elf-long','Isuzu Elf Long Pariwisata Eksekutif','Armada elf long bertenaga tinggi yang lincah menaklukkan tanjakan wisata perbukitan dengan kapasitas lega untuk komunitas dan rombongan keluarga.','https://images.unsplash.com/photo-1570125909232-eb263c188f7e?auto=format&fit=crop&w=400&q=80','Rekomendasi 15-19 Org','Kapasitas 15 - 19 Kursi Penumpang',10,19,850000,array['AC Dingin Tiap Baris','Audio & Karaoke Mikrofon','Driver + BBM Termasuk','Bagasi Belakang Luas untuk Oleh-Oleh']::text[],array['Stasiun Kereta Api','Rest Area Tol','Titik Kumpul Rombongan']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('medium-bus','Medium Bus Pariwisata Jetbus (31 Seat)','Bus pariwisata kelas medium dengan konfigurasi kursi 2-2 reclining seat untuk kenyamanan maksimal rombongan besar sekolah, instansi, atau kantor.','https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?auto=format&fit=crop&w=400&q=80','Rekomendasi 25-35 Org','Kapasitas 25 - 35 Kursi Penumpang',15,35,1600000,array['AC Ducting Tiap Kursi','Reclining Seat Empuk Ergonomis','TV LCD & Audio Karaoke','Driver Berlisensi + Co-Driver','Asuransi Jasa Raharja']::text[],array['Kantor / Sekolah / Kampus','Stasiun Kereta','Rest Area']::text[]) on conflict (slug) do nothing;
insert into transport_options (slug,name,description,image_url,badge,capacity_text,min_capacity,max_capacity,price,facilities,pickup_points) values ('big-bus','Big Bus Pariwisata SHD (Super High Deck 50 Seat)','Bus pariwisata super premium dengan toilet kabin, bagasi tembus motor/koper besar, dan suspensi udara empuk untuk perjalanan wisata rombongan masal.','https://images.unsplash.com/photo-1570125909232-eb263c188f7e?auto=format&fit=crop&w=400&q=80','Super Rombongan 40-55 Org','Kapasitas 40 - 55 Kursi Penumpang',30,55,2750000,array['Toilet Bersih Dalam Bus','AC Central Dingin Maksimal','Dispenser Air Panas/Dingin','Port Charger Tiap Baris','2 Driver Senior + Crew','Asuransi Jasa Raharja Penuh']::text[],array['Titik Penjemputan Rombongan','Bandara / Stasiun','Kantor Pusat']::text[]) on conflict (slug) do nothing;

