with u as (select id from umkm_partners where name='Mitra UMKM Sate Maranggi Hj. Yetty' limit 1), fi as (insert into food_items (umkm_id,name,description,image_url,category,base_price,spicy_options) select u.id,'Sate Maranggi Khas Purwakarta (10 Tusuk)','Sate daging bakar bumbu rempah ketumbar manis gurih khas Purwakarta, disajikan dengan irisan tomat segar dan cabai rawit pedas uleg.','https://images.unsplash.com/photo-1555939594-58d7cb561ad1?auto=format&fit=crop&w=500&q=80','Makanan Utama',35000,array['Tidak Pedas (Manis Gurih)','Pedas Sedang (Sambal Tomat 2 Sendok)','Pedas Nampol (Ekstra Rawit Merah)']::text[] from u where not exists (select 1 from food_items x where x.name='Sate Maranggi Khas Purwakarta (10 Tusuk)') returning id)
,
ins_v as (insert into food_variants (food_id,group_name,label,price_diff) select * from (values ((select id from fi),'Pilihan Jenis Daging','Sate Daging Sapi Lemak Manis (Favorit)',0),((select id from fi),'Pilihan Jenis Daging','Sate Daging Sapi Murni (Tanpa Lemak)',5000),((select id from fi),'Pilihan Jenis Daging','Sate Kambing Muda Empuk Spesial',8000),((select id from fi),'Pilihan Jenis Daging','Sate Ayam Bumbu Maranggi Gurih',-5000)) v(a,b,c,d) where a is not null),
ins_s as (insert into food_sides (food_id,label,price) select * from (values ((select id from fi),'Tambah Lontong Daun Pisang Pulen',5000),((select id from fi),'Tambah Nasi Timbel Bungkus Daun',6000),((select id from fi),'Ekstra Sambal Tomat Pedas Uleg',3000),((select id from fi),'Kerupuk Kulit Sapi Renyah',4000)) v(a,b,c) where a is not null)
select 1;
with u as (select id from umkm_partners where name='Dapur Nasi Liwet Kastrol Ibu Nunung' limit 1), fi as (insert into food_items (umkm_id,name,description,image_url,category,base_price,spicy_options) select u.id,'Paket Nasi Liwet Kastrol Khas Sunda Komplit','Nasi liwet wangi daun salam serai disajikan hangat dengan lauk pilihan, tahu tempe goreng, lalapan segar, dan sambal terasi dadak.','https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=500&q=80','Makanan Utama',38000,array['Sambal Terasi Jeruk Limau (Sedang)','Sambal Dadak Tomat Segar (Pedas)','Tanpa Sambal (Lalapan Saja)']::text[] from u where not exists (select 1 from food_items x where x.name='Paket Nasi Liwet Kastrol Khas Sunda Komplit') returning id)
,
ins_v as (insert into food_variants (food_id,group_name,label,price_diff) select * from (values ((select id from fi),'Pilihan Lauk Utama','Ayam Goreng Lengkuas Rempah',0),((select id from fi),'Pilihan Lauk Utama','Ayam Bakar Madu Gurih',2000),((select id from fi),'Pilihan Lauk Utama','Ikan Nila Goreng Kering Renyah',-3000),((select id from fi),'Pilihan Lauk Utama','Bebek Goreng Kremes Sambal Ijo',9000)) v(a,b,c,d) where a is not null),
ins_s as (insert into food_sides (food_id,label,price) select * from (values ((select id from fi),'Ikan Asin Jambal Roti Crispy',6000),((select id from fi),'1 Papan Pete Bakar / Goreng',10000),((select id from fi),'1 Mangkok Sayur Asem Sunda Hangat',7000)) v(a,b,c) where a is not null)
select 1;
