ins_s as (insert into food_sides (food_id,label,price) select * from (values ((select id from fi),'Ekstra Daging Kelapa Muda',3000),((select id from fi),'Tambah Tape Ketan Hitam Manis',3000),((select id from fi),'Tambah Kerokan Buah Alpukat',5000)) v(a,b,c) where a is not null)
